<?php
/**
 * Prints config.php for the deploy workflow, built from environment variables.
 *
 * TEAMSSTATUS_USERS is a JSON object: {"name@example.com": "<Entra object ID>"}
 */

declare(strict_types=1);

function fail(string $message): never
{
    fwrite(STDERR, "write-config: $message\n");
    exit(1);
}

$config = [];
foreach (['tenant_id' => 'ENTRA_TENANT_ID', 'client_id' => 'ENTRA_CLIENT_ID', 'client_secret' => 'ENTRA_CLIENT_SECRET'] as $key => $name) {
    $config[$key] = getenv($name) ?: fail("$name is not set");
}

try {
    $users = json_decode(getenv('TEAMSSTATUS_USERS') ?: '', true, flags: JSON_THROW_ON_ERROR);
} catch (JsonException $e) {
    fail('TEAMSSTATUS_USERS is not valid JSON: ' . $e->getMessage());
}
if (!is_array($users) || $users === [] || array_is_list($users)) {
    fail('TEAMSSTATUS_USERS must be a JSON object like {"name@example.com": "<Entra object ID>"}');
}
foreach ($users as $id) {
    if (!is_string($id) || !preg_match('/^[0-9a-f]{8}-([0-9a-f]{4}-){3}[0-9a-f]{12}$/i', $id)) {
        fail('TEAMSSTATUS_USERS: every value must be an Entra object ID (GUID)');
    }
}
$config['users'] = $users;

echo "<?php\n// Generated by the deploy workflow. Changes on the server are overwritten.\nreturn ",
    var_export($config, true), ";\n";
